use std::sync::Mutex;
use std::sync::atomic::{AtomicBool, AtomicU8, Ordering};
use std::sync::mpsc::{Receiver, TryRecvError};

use serde_json::Value;

const RUNNING: u8 = 0;
const COMPLETED: u8 = 1;
const CANCELLED: u8 = 2;
const FAILED: u8 = 3;

pub(crate) struct SearchSession {
    receiver: Mutex<Receiver<Value>>,
    state: AtomicU8,
    cancelled: AtomicBool,
}

impl SearchSession {
    pub(crate) fn new(receiver: Receiver<Value>) -> Self {
        Self {
            receiver: Mutex::new(receiver),
            state: AtomicU8::new(RUNNING),
            cancelled: AtomicBool::new(false),
        }
    }

    pub(crate) fn is_cancelled(&self) -> bool {
        self.cancelled.load(Ordering::Acquire)
    }

    pub(crate) fn mark_completed(&self) {
        self.state.store(COMPLETED, Ordering::Release);
    }

    pub(crate) fn mark_cancelled(&self) {
        self.cancelled.store(true, Ordering::Release);
        self.state.store(CANCELLED, Ordering::Release);
    }

    #[allow(dead_code)]
    pub(crate) fn mark_failed(&self) {
        self.state.store(FAILED, Ordering::Release);
    }

    pub(crate) fn state_name(&self) -> &'static str {
        match self.state.load(Ordering::Acquire) {
            COMPLETED => "completed",
            CANCELLED => "cancelled",
            FAILED => "failed",
            _ => "running",
        }
    }

    pub(crate) fn read_unseen(&self, max_items: usize) -> (Vec<Value>, bool) {
        let receiver = self
            .receiver
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let mut items = Vec::with_capacity(max_items);
        let mut exhausted = false;

        for _ in 0..max_items {
            match receiver.try_recv() {
                Ok(item) => items.push(item),
                Err(TryRecvError::Empty | TryRecvError::Disconnected) => {
                    exhausted = true;
                    break;
                }
            }
        }

        let terminal = self.state.load(Ordering::Acquire) != RUNNING;
        let done = terminal && exhausted;
        (items, done)
    }
}
